import { z } from 'zod';
import type { JsonValue } from '../models/form-settings.model';

/** Identifier used for custom fields and rows (generated by the client, e.g. `field_k3j9x2`). */
export const identifierSchema = z
  .string()
  .regex(
    /^[A-Za-z][A-Za-z0-9_-]{0,63}$/,
    'Must start with a letter and contain only letters, digits, "_" or "-" (max 64 chars)',
  );

export const uuidSchema = z.uuid({ error: 'Must be a valid UUID' });

export const idParamSchema = z.object({ id: uuidSchema });

/** Hard limits of a JSON value stored on a task (expression results, groups, dynamic lists, file references). */
export const JSON_VALUE_LIMITS = {
  maxDepth: 8,
  maxStringLength: 1000,
  maxArrayItems: 100,
  maxObjectKeys: 100,
} as const;

interface JsonProblem {
  path: (string | number)[];
  message: string;
}

/**
 * Finds the first value that breaks the JSON limits. Each array / object level counts as one level of depth.
 * @returns the problem and its path relative to the checked value, or `null` when the value is valid.
 */
function findJsonProblem(value: unknown, depth: number, path: (string | number)[]): JsonProblem | null {
  const { maxDepth, maxStringLength, maxArrayItems, maxObjectKeys } = JSON_VALUE_LIMITS;

  if (value === null || typeof value === 'boolean') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? null : { path, message: 'Must be a finite number' };
  if (typeof value === 'string') {
    return value.length > maxStringLength ? { path, message: `Must be at most ${maxStringLength} characters` } : null;
  }
  if (typeof value !== 'object') return { path, message: 'Must be a JSON value' };
  if (depth > maxDepth) return { path, message: `Values can be nested at most ${maxDepth} levels deep` };

  const entries: [string | number, unknown][] = Array.isArray(value) ? [...value.entries()] : Object.entries(value);
  if (Array.isArray(value) && entries.length > maxArrayItems) {
    return { path, message: `Must contain at most ${maxArrayItems} items` };
  }
  if (!Array.isArray(value) && entries.length > maxObjectKeys) {
    return { path, message: `Must contain at most ${maxObjectKeys} properties` };
  }

  for (const [key, item] of entries) {
    const problem = findJsonProblem(item, depth + 1, [...path, key]);
    if (problem) return problem;
  }
  return null;
}

/**
 * Any JSON value within {@link JSON_VALUE_LIMITS}: protects the storage from huge or deeply nested payloads.
 * What the value must look like is decided later by the component it belongs to (see task-values.validator).
 */
export const jsonValueSchema = z.custom<JsonValue>().superRefine((value, ctx) => {
  const problem = findJsonProblem(value, 1, []);
  if (problem) ctx.addIssue({ code: 'custom', path: problem.path, message: problem.message });
});
